import sys,json,base64,zlib
def gz(s):
    pad='='*(-len(s)%4)
    return json.loads(zlib.decompress(base64.urlsafe_b64decode(s+pad)))
d=json.load(open(sys.argv[1]))
print("KEYS in export output:", sorted(d.keys()))
if 'DIRENV_DIFF' in d:
    diff=gz(d['DIRENV_DIFF'])
    print("DIFF.p keys:", sorted(diff['p'].keys()))
    print("DIFF.n keys:", sorted(diff['n'].keys()))
    for k in sorted(diff['n']):
        if not k.startswith('DIRENV_'): print("   n[%s]=%r"%(k,diff['n'][k]))
if 'DIRENV_WATCHES' in d:
    for w in gz(d['DIRENV_WATCHES']): print("WATCH:", w['path'], w['exists'], w['modtime'])
EOF
